#define _XOPEN_SOURCE 700

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "format.h"
#include "screen.h"
#include "util.h"

static const struct attr plain = { COLOR_DEFAULT, COLOR_DEFAULT, 0 };

struct sbuf {
	char *p;
	size_t len, cap;
};

static void sbuf_add(struct sbuf *b, const char *s, size_t n)
{
	if (b->len + n + 1 > b->cap) {
		b->cap = (b->len + n + 1) * 2;
		b->p = xrealloc(b->p, b->cap);
	}
	memcpy(b->p + b->len, s, n);
	b->len += n;
	b->p[b->len] = '\0';
}

static void sbuf_str(struct sbuf *b, const char *s)
{
	sbuf_add(b, s, strlen(s));
}

static void blank(struct cell *c, struct attr attr)
{
	c->text[0] = ' ';
	c->text[1] = '\0';
	c->attr = attr;
}

void screen_init(struct screen *s, size_t cols, size_t rows, int color)
{
	s->cols = 0;
	s->rows = 0;
	s->back = NULL;
	s->front = NULL;
	s->color = color;
	s->truecolor = 0;
	s->fg = COLOR_DEFAULT;
	s->bg = COLOR_DEFAULT;
	s->cursor_on = 0;
	s->cursor_x = 0;
	s->cursor_y = 0;
	s->shown_x = 0;
	s->shown_y = 0;
	screen_resize(s, cols, rows);
}

void screen_resize(struct screen *s, size_t cols, size_t rows)
{
	s->cols = cols;
	s->rows = rows;
	s->back = xrealloc(s->back, (cols * rows + 1) * sizeof *s->back);
	s->front = xrealloc(s->front, (cols * rows + 1) * sizeof *s->front);
	screen_clear(s);
	screen_invalidate(s);
}

void screen_free(struct screen *s)
{
	free(s->back);
	free(s->front);
	s->back = NULL;
	s->front = NULL;
}

/* The terminal shows something unknown: the next flush sends every cell. */
void screen_invalidate(struct screen *s)
{
	s->valid = 0;
	s->cursor_shown = -1;
}

/*
 * The text and background of the whole screen. Every cell changes with
 * them, so a change sends every cell anew.
 */
void screen_colors(struct screen *s, unsigned long fg, unsigned long bg)
{
	if (s->fg == fg && s->bg == bg)
		return;
	s->fg = fg;
	s->bg = bg;
	screen_invalidate(s);
}

void screen_clear(struct screen *s)
{
	size_t i;

	for (i = 0; i < s->cols * s->rows; i++)
		blank(&s->back[i], plain);
	s->cursor_on = 0;
}

/* A cell overwritten in the middle of a wide character takes its other half. */
static void put(struct screen *s, size_t x, size_t y, const char *text,
    size_t len, size_t width, struct attr attr)
{
	struct cell *row = s->back + y * s->cols;
	size_t end = x + width;

	if (row[x].text[0] == '\0' && x > 0)
		blank(&row[x - 1], row[x - 1].attr);
	if (end < s->cols && row[end].text[0] == '\0')
		blank(&row[end], row[end].attr);
	memcpy(row[x].text, text, len);
	row[x].text[len] = '\0';
	row[x].attr = attr;
	if (width == 2) {
		row[x + 1].text[0] = '\0';
		row[x + 1].attr = attr;
	}
}

/*
 * Writes text from column x of row y into width columns, cut with an
 * ellipsis when longer, the rest filled with spaces (right: on the left).
 * Returns the columns the text took.
 */
size_t screen_text(struct screen *s, size_t x, size_t y, size_t width,
    const char *text, struct attr attr, int right)
{
	struct cell *last = NULL;
	char *fit;
	const char *p;
	size_t used, pad = 0, w, len, n, i;

	if (y >= s->rows || x >= s->cols)
		return 0;
	if (width > s->cols - x)
		width = s->cols - x;
	fit = text_fit(text, width);
	used = text_width(fit);
	if (right && used < width)
		pad = width - used;
	for (i = 0; i < pad; i++)
		put(s, x + i, y, " ", 1, 1, attr);
	used = pad;
	for (p = fit; *p != '\0'; p += len) {
		w = text_char_width(p, &len);
		if (w == 0) {
			/* A combining mark joins the character before it. */
			if (last != NULL) {
				n = strlen(last->text);
				if (n + len < sizeof last->text) {
					memcpy(last->text + n, p, len);
					last->text[n + len] = '\0';
				}
			}
			continue;
		}
		if (used + w > width || len >= sizeof last->text)
			break;
		put(s, x + used, y, p, len, w, attr);
		last = &s->back[y * s->cols + x + used];
		used += w;
	}
	free(fit);
	w = used - pad;
	for (; used < width; used++)
		put(s, x + used, y, " ", 1, 1, attr);
	return right ? width : w;
}

/* The text of row y without trailing spaces, for the tests. */
char *screen_line(const struct screen *s, size_t y)
{
	struct sbuf b = { NULL, 0, 0 };
	size_t x;

	sbuf_add(&b, "", 0);
	for (x = 0; x < s->cols; x++)
		sbuf_str(&b, s->back[y * s->cols + x].text);
	while (b.len > 0 && b.p[b.len - 1] == ' ')
		b.p[--b.len] = '\0';
	return b.p;
}

static int same(const struct cell *a, const struct cell *b)
{
	return strcmp(a->text, b->text) == 0 && a->attr.fg == b->attr.fg &&
	    a->attr.bg == b->attr.bg && a->attr.style == b->attr.style;
}

/* One channel's step in the 6×6×6 cube of the 256 colours. */
static int cube_step(int v)
{
	return v < 48 ? 0 : v < 115 ? 1 : (v - 35) / 40;
}

static int cube_level(int step)
{
	return step == 0 ? 0 : 55 + 40 * step;
}

static long distance(int r, int g, int b, int r2, int g2, int b2)
{
	return (long)(r - r2) * (r - r2) + (long)(g - g2) * (g - g2) +
	    (long)(b - b2) * (b - b2);
}

/* The nearest of the 256 colours: the cube or the grey ramp. */
int screen_nearest(unsigned long rgb)
{
	int r = (int)(rgb >> 16 & 255), g = (int)(rgb >> 8 & 255),
	    b = (int)(rgb & 255), cr, cg, cb, grey, level;

	cr = cube_step(r);
	cg = cube_step(g);
	cb = cube_step(b);
	grey = (r + g + b) / 3;
	grey = grey < 8 ? 0 : grey > 238 ? 23 : (grey - 3) / 10;
	level = 8 + 10 * grey;
	if (distance(r, g, b, level, level, level) <
	    distance(r, g, b, cube_level(cr), cube_level(cg), cube_level(cb)))
		return 232 + grey;
	return 16 + 36 * cr + 6 * cg + cb;
}

/* The parameters of a colour; base is 30 for the text, 40 the background. */
static void sgr_color(struct sbuf *b, const struct screen *s,
    unsigned long c, int base)
{
	char num[32];

	if (c == COLOR_DEFAULT)
		return;
	if (c < 8)
		snprintf(num, sizeof num, ";%d", base + (int)c);
	else if (c < 16)
		snprintf(num, sizeof num, ";%d", base + 60 + (int)c - 8);
	else if (c < 256)
		snprintf(num, sizeof num, ";%d;5;%d", base + 8, (int)c);
	else if (s->truecolor)
		snprintf(num, sizeof num, ";%d;2;%d;%d;%d", base + 8,
		    (int)(c >> 16 & 255), (int)(c >> 8 & 255), (int)(c & 255));
	else
		snprintf(num, sizeof num, ";%d;5;%d", base + 8,
		    screen_nearest(c));
	sbuf_str(b, num);
}

static void sgr(struct sbuf *b, const struct screen *s, struct attr a)
{

	sbuf_str(b, "\033[0");
	if (a.style & STYLE_BOLD)
		sbuf_str(b, ";1");
	if (a.style & STYLE_DIM)
		sbuf_str(b, ";2");
	if (a.style & STYLE_UNDERLINE)
		sbuf_str(b, ";4");
	if (a.style & STYLE_REVERSE)
		sbuf_str(b, ";7");
	if (s->color) {
		sgr_color(b, s, a.fg == COLOR_DEFAULT ? s->fg : a.fg, 30);
		sgr_color(b, s, a.bg == COLOR_DEFAULT ? s->bg : a.bg, 40);
	}
	sbuf_str(b, "m");
}

static void move_to(struct sbuf *b, size_t x, size_t y)
{
	/* Room for two 20-digit size_t values, or gcc warns of truncation. */
	char seq[48];

	snprintf(seq, sizeof seq, "\033[%zu;%zuH", y + 1, x + 1);
	sbuf_str(b, seq);
}

/*
 * The bytes that bring the terminal from front to back: a cursor move
 * only where the changed cells are not contiguous, attributes only where
 * they change. After the last column the cursor position is not trusted
 * (terminals differ in when they wrap). NULL when nothing changed.
 */
char *screen_flush(struct screen *s, size_t *len)
{
	struct sbuf b = { NULL, 0, 0 };
	struct cell *c;
	struct attr cur = plain;
	size_t x, y, i, cx = (size_t)-1, cy = (size_t)-1;
	int known = 0, wide;

	for (y = 0; y < s->rows; y++) {
		for (x = 0; x < s->cols; x++) {
			i = y * s->cols + x;
			c = &s->back[i];
			if (c->text[0] == '\0')
				continue;
			wide = x + 1 < s->cols && s->back[i + 1].text[0] == '\0';
			if (s->valid && same(c, &s->front[i]) &&
			    (!wide || same(&s->back[i + 1], &s->front[i + 1])))
				continue;
			if (cx != x || cy != y)
				move_to(&b, x, y);
			if (!known || cur.fg != c->attr.fg ||
			    cur.bg != c->attr.bg || cur.style != c->attr.style) {
				sgr(&b, s, c->attr);
				cur = c->attr;
				known = 1;
			}
			sbuf_str(&b, c->text);
			cx = x + (wide ? 2 : 1);
			cy = y;
			if (cx >= s->cols)
				cx = (size_t)-1;
		}
	}
	if (known && (cur.fg != plain.fg || cur.bg != plain.bg ||
	    cur.style != plain.style))
		sbuf_str(&b, "\033[0m");
	if (s->cursor_on && (b.len > 0 || s->cursor_shown != 1 ||
	    s->cursor_x != s->shown_x || s->cursor_y != s->shown_y)) {
		move_to(&b, s->cursor_x, s->cursor_y);
		s->shown_x = s->cursor_x;
		s->shown_y = s->cursor_y;
	}
	if (s->cursor_on && s->cursor_shown != 1) {
		sbuf_str(&b, "\033[?25h");
		s->cursor_shown = 1;
	} else if (!s->cursor_on && s->cursor_shown != 0) {
		sbuf_str(&b, "\033[?25l");
		s->cursor_shown = 0;
	}
	memcpy(s->front, s->back, s->cols * s->rows * sizeof *s->front);
	s->valid = 1;
	*len = b.len;
	return b.p;
}
